"""Lossless JSON numbers for complete request identity and portable receipts.

Unknown fields still belong to the idempotency body. Binary floats would merge
distinct decimal values, or overflow an otherwise valid JSON number to infinity.
"""
from decimal import Decimal
import json


def reject_constant(value):
    raise ValueError('Non-JSON number')


def loads(value):
    return json.loads(value, parse_float=Decimal, parse_constant=reject_constant)


def dumps(value):
    if isinstance(value, Decimal):
        if not value.is_finite():
            raise ValueError('Non-JSON number')
        return str(value)
    if isinstance(value, dict):
        return '{' + ','.join(json.dumps(k, ensure_ascii=True) + ':' + dumps(v)
                              for k, v in value.items()) + '}'
    if isinstance(value, list):
        return '[' + ','.join(dumps(v) for v in value) + ']'
    return json.dumps(value, ensure_ascii=True, allow_nan=False, separators=(',', ':'))
"""The API's type, format and domain-error boundary."""
import math
import re
from decimal import Decimal


class APIError(Exception):
    def __init__(self, status, code, message=None):
        self.status = status
        self.code = code
        self.message = message or code.replace('_', ' ').capitalize()
        super().__init__(self.message)


def fail(code='validation_failed', status=422, message=None):
    raise APIError(status, code, message)


def require(condition, code='validation_failed', status=422):
    if not condition:
        fail(code, status)


def object_body(value):
    require(isinstance(value, dict), 'malformed_request', 400)
    return value


def field(body, name, kind, *, maximum=None):
    require(name in body)
    value = body[name]
    require(type(value) is kind, 'malformed_request', 400)
    if maximum is not None:
        require(len(value) <= maximum)
    return value


def identifier(body, name):
    value = field(body, name, str, maximum=64)
    require(bool(value))
    return value


def integer(body, name, minimum=1):
    value = field(body, name, int)
    require(value >= minimum)
    return value


def party(body):
    value = body.get('party_size')
    require((type(value) is int and value >= 1) or
            (type(value) is float and math.isfinite(value) and value >= 1 and value.is_integer()) or
            (type(value) is Decimal and value.is_finite() and value >= 1 and value == value.to_integral_value()))
    return int(value)


def email(body):
    value = field(body, 'email', str)
    require(re.fullmatch(r'[^\s@]+@[^\s@]+', value) is not None)
    return value


def same_json(left, right):
    """JSON value equality: object order immaterial, booleans are not numbers."""
    if type(left) in (int, float, Decimal) and type(right) in (int, float, Decimal):
        return left == right
    if type(left) is not type(right):
        return False
    if isinstance(left, dict):
        return left.keys() == right.keys() and all(same_json(left[k], right[k]) for k in left)
    if isinstance(left, list):
        return len(left) == len(right) and all(same_json(a, b) for a, b in zip(left, right))
    return left == right
